const GABARITO_URL="https://conhecimento.fgv.br/sites/default/files/concursos/gabarito-definitivo-fhemig-retificado-01.11.2023.pdf";
const LOTES=[{"codigo":"cns301","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/profissional-de-enfermagem-penf-enfermeiro-30h-nivel-ivcns301-tipo-1.pdf","cargo":"Enfermeiro 30h","itens":[{"n":1,"disciplina":"Língua Portuguesa","tema":"Figuras de Linguagem e Vícios de Linguagem","enunciado":"Nas opções a seguir, há a indicação de uma figura de linguagem com um exemplo correspondente. Assinale a opção em que a indicação do exemplo está correta.","alternativas":["Personificação: Por mim, teria evitado casar até mesmo com a sabedoria, caso ela me quisesse.","Antítese: A esposa diligente é a coroa do seu marido; e a que lhe causa problemas é o câncer dos seus ossos.","Eufemismo: Um marido nunca deve ser o primeiro a pegar no sono nem o último a acordar.","Paradoxo: Estou para realizar minha última viagem, um grande salto no escuro.","Hipérbole: O infinito é uma esfera infinita, cujo centro está em toda parte e a circunferência em nenhum lugar"],"correta":"A"},{"n":2,"disciplina":"Língua Portuguesa","tema":"Estrutura e Formação de Palavras","enunciado":"Biscoito significa “cozido duas vezes” ( bis+ coctu ), pois era, na verdade, o que acontecia: coziam a massa duas vezes para que, endurecida pela desidratação, pudesse durar mais tempo, o que era muito útil nas viagens demoradas pelo mar. BIS é um radical latino - também assume a forma BI ( biforme) ou BA ( balança) -, que entra como primeiro elemento na construção de novos vocábulos, com valor semântico de “dois ou duas vezes”. Assinale a opção em que, usando esse radical, o vocábulo indicado está correto.","alternativas":["Que tem dois pés: bipedestre.","Que ocorre de dois em dois meses: bimensal.","Que ocorre uma vez a cada dois anos: bianual.","Casado com duas esposas: bígamo.","Que fala duas línguas: biarticulado"],"correta":"D"},{"n":3,"disciplina":"Língua Portuguesa","tema":"Ortografia e Acentuação","enunciado":"Assinale a opção em que todos os vocábulos grafados com e ou i estão escritos corretamente.","alternativas":["adiante / lampião / crâneo.","veado / pior / casimira.","palitó / Pireneus / arrepio.","irriquieto / digladiar / dilapidar.","crioulo / pátio / confissionário"],"correta":"B"},{"n":4,"disciplina":"Língua Portuguesa","tema":"Interpretação de Textos","enunciado":"“Uns homens sobem por leves como os vapores e gazes, outros como os projetis pela força do engenho e dos talentos.” Marquês de Maricá. Sobre a estruturação dessa frase, assinale a observação incorreta.","alternativas":["O termo “Uns” corresponde estruturalmente a “outros”.","A forma verbal “sobem” está omitida na oração seguinte.","A preposição “por” tem o valor de “causa”.","O termo “como os vapores e gases” corresponde estruturalmente a “como os projetis”.","Os termos “por leves” e “pela força dos engenhos e dos talentos” correspondem-se estrutural e semanticamente"],"correta":"E"},{"n":5,"disciplina":"Língua Portuguesa","tema":"Semântica e Significação","enunciado":"O processo de reificação corresponde a tratar -se o ser humano como uma coisa, um objeto qualquer. Esse processo aparece nas opções a seguir, à exceção de uma . Assinale-a.","alternativas":["As garrafas de refrigerantes, quando retiradas da geladeira, ficam imediatamente suadas.","Nas grandes cidades, os passageiros vêm espremidos nos ônibus para o trabalho.","Após a violenta briga no final do show, alguns assistentes tinham a cara amassada.","Alguns clientes do bar, após beberem por muito tempo, saíam derrapando pelo chão de cerâmica.","O problema com as crianças é que elas não são retornáveis"],"correta":"A"},{"n":8,"disciplina":"Língua Portuguesa","tema":"Variação Linguística","enunciado":"Assinale a opção que apresenta uma variação popular de linguagem.","alternativas":["Meu computador parou de funcionar; eu já deveria ter trocado o bloco de alimentação, o que se chama comumente power supply.","Ah! Não! Roubaram meu dinheiro! Estou desesperado!","Encontrei um pequeno apa rtamento em Paris para passar férias e eu o adorei! Adorei!!","Observem que o tal consórcio da imprensa reúne grandes jornais relacionados a uma mesma ideologia.","Dizem que o termo brega é proveniente de Nóbrega, nome de uma rua de má fama em São Paulo."],"correta":"D"},{"n":9,"disciplina":"Língua Portuguesa","tema":"Interpretação de Textos","enunciado":"Nas situações de comunicação a seguir, estão indicados, correta e respectivamente, o emissor (o produtor da mensagem), o receptor (a quem se dirige a mensagem) e o código (o meio empregado na comunicação). I. Rosa leu o folheto do supermercado e ficou contente de ver, com 25% de redução, a foto das suas frutas preferidas / O supermercado – Rosa – verbal + imagens. II. Duda começou a latir para mostrar a seu dono que estava satisfeita em vê-lo / Duda – o dono – latidos. III. Diante do pedido de informação do turista, um transeunte respondeu, dando de ombros / o turista – o transeunte – verbal e gestual. Está correto o que se afirma em","alternativas":["I, apenas.","III, apenas.","I e II, apenas.","II e III, apenas.","I, II e III"],"correta":"E"},{"n":10,"disciplina":"Língua Portuguesa","tema":"Coesão e Coerência","enunciado":"Leia o texto a seguir “Contrariamente ao que ocorria outrora, a excelência hoje não se afirma pela duração; a preeminência sobre grande número de competidores e concorrentes se afirma rapidamente e tem pouca duração.” Para evitar a repetiçã o da palavra sublinhada o autor do texto apelou para a seguinte estratégia:","alternativas":["elipse do termo.","substituição por sinônimo.","substituição por uma perífrase.","substituição por um pronome.","ampliação do termo inicial. Raciocínio Lógico"],"correta":"C"},{"n":11,"disciplina":"Raciocínio Lógico e Matemática","tema":"Argumentação Lógica","enunciado":"Marcos estuda sempre durante o dia. Nos 5 dias da última semana, de segunda -feira a sexta -feira, em exatos 3 dias, ele estudou apenas 5 horas. O número de horas de estudo na segunda-feira foi igual ao número de horas de estudo na quinta- feira. Na quarta -feira, ele estudou uma hora a mais do que na terça-feira e uma hora a menos do que na segunda-feira. Ao todo, nesses 5 dias, Marcos estudou","alternativas":["17 horas.","20 horas.","22 horas.","27 horas.","32 horas"],"correta":"C"},{"n":12,"disciplina":"Raciocínio Lógico e Matemática","tema":"Equivalências e Negações","enunciado":"A proposição “Se eu passo em concurso público, não fico desempregado” é logicamente equivalente a","alternativas":["“Se eu não passo em concurso público, não fico desempregado.”","“Se eu não passo em concurso público, fico desempregado.”","“Eu passo em concurso público e não fico desempregado.”","“Se eu fico desempregado, não passo em concurso público.”","“Se eu não fico desempregado, não passo em concurso público.”"],"correta":"D"},{"n":13,"disciplina":"Raciocínio Lógico e Matemática","tema":"Probabilidade","enunciado":"Em uma sacola, há 40 bolas. Essas bolas, ou são brancas, ou são azuis. Se uma das bolas brancas for retirada da sacola, a probabilidade de que uma bola sorteada ao acaso seja branca passa a ser 5 13. A quantidade de bolas azuis dentro da sacola é","alternativas":["25.","24.","23.","16.","15"],"correta":"B"},{"n":14,"disciplina":"Raciocínio Lógico e Matemática","tema":"Estatística Descritiva","enunciado":"Considere uma lista formada por 5 números inteiros positivos cuja mediana e média aritmética valem, ambas, 8. As médias aritméticas dos 4 maiores valores e dos 4 menores valores dessa lista são, respectivamente, 8,50 e 7,25. Assinale a opção que mostra o número que não pode integrar essa lista.","alternativas":["6.","7.","8.","9.","10"],"correta":"E"},{"n":15,"disciplina":"Raciocínio Lógico e Matemática","tema":"Razão, Proporção e Porcentagem","enunciado":"Dois pentágonos regulares convexos têm áreas medindo 54cm 2 e 6cm2. É correto afirmar que a razão entre a medida do lado do pentágono de maior área e o perímetro do pentágono de menor área é","alternativas":["0,2.","0,6.","0,8.","3.","9. Atualidades"],"correta":"B"},{"n":21,"disciplina":"Legislação do SUS","tema":"Constituição Federal - Saúde","enunciado":"A respeito dos termos que compõem a expressão Sistema Único de Saúde (SUS), analise as afirmativas a seguir. I. O termo sistema indica o somatório das ações assistenciais direcionadas a segmentos populacionais espec íficos, classificados com base em critérios nosológicos. II. O termo único refere-se à universalização do acesso a todas as ações e cuidados da rede assistencial pública e privada contratada e ao comando único em cada esfera de governo. III. O termo saúde é entendido como resultante e condicionante de condições de vida, trabalho e acesso a bens e serviços e, portanto, como componente da cidadania e não apenas como ausência de doença. Está correto o que se afirma em","alternativas":["I, apenas.","II, apenas.","I e II, apenas.","II e III, apenas.","I, II e III"],"correta":"D"},{"n":22,"disciplina":"Legislação do SUS","tema":"Lei 8.080/1990 - Princípios e Diretrizes","enunciado":"O Sistema Único de Saúde (SUS) pauta -se em um conjunto de princípios e diretrizes organizativas, traduzidas corretamente em ações voltadas para","alternativas":["o fomento da participação popular direta, mediante a criação de Comissões Intergestores Tripartites e de Secretarias Municipais de Saúde.","a promoção da integralidade, para superar a situação de desigualdade na assistência à saúde da população e investir mais onde a carência é maior.","a cen tralização da prestação dos serviços no nível estadual, de modo a assegurar maior qualidade e garantir o controle e a fiscalização por parte dos cidadãos.","a obrigatoriedade do atendimento público de qualquer cidadão, com o estabelecimento da cobrança p rogressiva em dinheiro com base em faixas de renda socioeconômicas.","a organização dos serviços em níveis crescentes de complexidade, circunscritos a uma determinada área geográfica e planejados a partir de critérios epidemiológicos"],"correta":"E"},{"n":23,"disciplina":"Legislação do SUS","tema":"Lei 8.080/1990 - Organização e Competências","enunciado":"Em relação ao modo como os entes federados devem se articular para formular, implementar e avaliar a política de saúde, considerando a L ei nº 8.080/90, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) É atribuição específica dos Municípios definir, coordenar e executar os programas de vigilância epidemiológica e sanitária. ( ) É uma prerrogativa comum a Estados e Municípios participar do controle dos agravos ao meio ambiente. ( ) Cabe à União, com recursos própr ios, financiar o Subsistema de Atenção à Saúde Indígena. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["V – V – F.","V – F – V.","F – V – V.","F – V – F.","V – V – V"],"correta":"C"},{"n":24,"disciplina":"Legislação do SUS","tema":"Direitos dos Usuários do SUS","enunciado":"O usuário do SUS possui o direito de decidir se seus familiares e acompanhantes deverão ser informados sobre seu estado de saúde, bem como tem o direito de ter acesso à anestesia em todas as situações em que for indicada. Essas garantias constam na Carta dos Direitos dos Usuários do SUS e materializa m um dos princípios básicos de cidadania que assegura ao brasileiro o ingresso digno nos sistemas de saúde, seja ele público ou privado. A esse respeito, assinale a opção que indica o princípio básico de cidadania que fundamenta os direitos do usuário do S US citados no trecho.","alternativas":["O acesso ordenado e organizado aos sistemas de saúde.","O tratamento adequado e efetivo para seu problema.","O atendimento que respeite a pessoa, os valores e os direitos do cidadão.","O atendimento humanizado, acolhedor e l ivre de qualquer discriminação.","O comprometimento dos gestores de saúde para que os princípios de cidadania do usuário do SUS sejam cumpridos"],"correta":"B"},{"n":25,"disciplina":"Legislação do SUS","tema":"Lei 8.080/1990 - Organização e Competências","enunciado":"A respeito da e strutura e funcionamento das instituições e suas relações com a gestão dos serviços de saúde, assinale a afirmativa que caracteriza corretamente um dos órgãos gestores do SUS.","alternativas":["O Conselho Nacional de Secretários de Saúde (Conass) representa os Estados e o Distrito Federal na Comissão Intergestores Tripartite (CIT) para tratar dos principais temas de saúde.","A Comissão Intergestores Tripartite (CIT) atua como espaço estratégico de reivindicação, formulação, controle e avaliação da execução das políticas públicas de saúde.","A Secretária Estadual da Saúde (SES) formula, norm atiza, coordena e fiscaliza o Sistema Único de Saúde, em articulação com o Conselho Nacional de Saúde, além de coordenar as ações de atendimento de alta complexidade.","As Comissões de Saúde são fóruns públicos que se reúnem de quatro em quatro anos, para avaliar e propor diretrizes para a formulação da política de saúde, com a participação de segmentos sociais representativos do SUS","A Comissão Intergestores Bipartite (CIB) é um órgão deliberativo, constituído por um f oro de negociação e pactuação entre gestores federais, estaduais e municipais, quanto aos aspectos operacionais do SUS."],"correta":"A"},{"n":26,"disciplina":"Legislação do SUS","tema":"Controle Social no SUS","enunciado":"Os Conselhos de Saúde são o principal canal de participação popular nas decisões da Administração Pública que envolvem o Sistema Único de Saúde (SU S) e, por isso, devem representar a diversidade social e cultural da sociedade. Por meio dos conselhos, a população pode colaborar de forma participativa do planejamento e da fiscalização das políticas públicas na área da saúde. https://www.saude.mg.gov.br/ (Adaptado) Considerando o trecho, assinale a opção que caracteriza corretamente o Conselho de Saúde.","alternativas":["É um órgão colegiado e paritário do SUS, presente em cada esfera de governo, constituído em situações emergenciais.","Os conselheiros são representantes do Ministério da Saúde, do Conselho Nacional de Secretários de Saúde e do Conselho Nacional de Secretarias Municipais de Saúde.","É uma instância deliberativa que analisa e aprova o plano de saúde e analisa e aprova o relatório de gestão.","Os conselheiros são indicados pelos respectivos gestores executivos da Saúde dos municípios, dos estados e do governo federal.","É uma instância submetida às secretarias de saúde dos municípios, dos estados e do governo federal"],"correta":"C"},{"n":27,"disciplina":"Legislação do SUS","tema":"Lei 8.080/1990 - Princípios e Diretrizes","enunciado":"As afirmativas a seguir indicam corretamente políticas que enfatizam a promoção da equidade em saúde no âmbito do Sistema Único de Saúde, à exceção de uma. Assinale-a.","alternativas":["Programa Nacional de Imunizações.","Política Nacional de Saúde Integral da População Negra.","Ações e Diretrizes em Saúde para a População em Situação de Rua.","Política Nacional de Saúde Integral das Populações do Campo e da Floresta.","Política Nacional de Saúde Integral de Lésbicas, Gays, Bissexuais, Travestis e Transexuais"],"correta":"A"},{"n":28,"disciplina":"Enfermagem","tema":"Política Nacional de Humanização","enunciado":"A Política Nacional de Humanização (PNH) está pautada em uma série de diretrizes que expressam métodos adotados para promover a inclusão em saúde. Sobre uma dessas diretrizes, leia a descrição a seguir. Processo constitutivo das práticas de produção e promoção de saúde que implica responsabilização do trabalhador/equipe pelo usuário, desde a sua chegada até a sua saída. Ouvindo sua queixa, considerando suas preocupações e angústias, fazendo uso de uma escuta qualificada que possibilite analis ar a demanda e garantir atenção integral, resolutiva e responsável. https://www.gov.br/saude/pt-br (Adaptado) Assinale a opção que indica a diretriz da PNH descrita no trecho acima.","alternativas":["Vínculo.","Co-gestão.","Participação.","Acolhimento.","Atendimento"],"correta":"D"},{"n":29,"disciplina":"Enfermagem","tema":"Segurança do Paciente","enunciado":"Considerando os requisitos de boas práticas de funcionamento para os serviços de saúde, detalhados na Resolução de Diretoria Colegiada RDC 63/2011, assinale a opção que indica o(s) serviço(s) de saúde que, segundo o seu tipo de atividade, documentação e registro, deve(m) se manter disponível(eis).","alternativas":["O projeto básico de arquitetura, com aprovação pelo Corpo de Bombeiros da Polícia Militar.","O controle de saúde ocupacional e o controle de qualidade da água.","Os contratos de serviços terceirizados e a certificação de qualidade em transparência pública.","A manutenção dos equipamentos e das condições adequadas para a comercialização de produtos químicos.","O gerenciamento de resíduos de serviços de saúde e o relatório de impacto ambiental"],"correta":"B"},{"n":30,"disciplina":"Enfermagem","tema":"Epidemiologia e Vigilância em Saúde","enunciado":"Para fortalecer a capacidade de resposta do Sistema Único de Saúde a emergências e desastres ocasionados pela seca e estiagem em Minas Gerais, a Secretaria de Saúde de Minas Gerais (SES/MG) elaborou um Plano de Preparação e Resposta (PPR) específico. Em relação às possíveis ações indicadas nesse documento para fazer frente às emergências ocasionadas pela seca e estiagem em Minas Gerais, analise as ações a seguir. I. No campo da atenção primária, estabelecer previamente articulação e acordos nas Re giões de Saúde, com outros setores e municípios, para cooperação e garantia de recursos, principalmente humanos, materiais e suprimentos de saúde. II. No campo da vigilância em saúde, identificar municípios mineiros atendidos pelo programa Transporte e Dis tribuição de Água Potável da Defesa Civil/MG e reportar ao Ministério da Saúde a situação do Estado de Minas Gerais no cenário de seca e estiagem. III. No campo da assistência farmacêutica, apoiar a vigilância em saúde no suprimento de hipoclorito de sódio a 2,5% para desinfecção caseira da água para consumo humano, quando necessário. São pertinentes as ações descritas em","alternativas":["I, apenas.","II, apenas.","I e II, apenas.","II e III, apenas.","I, II e III."],"correta":"E"},{"n":31,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"Considerando as diretrizes do Ministério da Saúde e da Sociedade Brasileira de Cardiologia, assinale a opção que indica um fator de risco para doença cardiovascular.","alternativas":["HDL-c < 60mg/DL","Pressão de pulso em idosos < 65 mmHg.","Triglicerídeos (TG) > 100mg/dL em jejum.","Circunferência abdominal > 95 cm para homens.","Circunferência abdominal > 88 cm para mulheres."],"correta":"E"},{"n":32,"disciplina":"Enfermagem","tema":"Administração de Medicamentos e Cálculos","enunciado":"Para tratamento da Covid -19 no Sistema Único de Saúde (SUS), em março de 2022, o Ministério da Saúde aprovou a incorporação do Baricitinibe 4mg. Acerca da administração desse medicamento, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O medicamento deve ser utilizado, exclusivamente, por pacientes com Covid -19 hospitalizados que necessitam de oxigênio por máscara ou cateter nasal, ou de alto fluxo de oxigênio ou ventilação não invasiva. ( ) O Baricitinibe 4 mg é contraindicado para mulheres grávidas e idosos acima de 65 anos. ( ) O Bar icitinibe pode ser administrado por via oral, tubo de alimentação por gastrostomia e sonda de alimentação nasogástrica ou orogástrica. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["V – F – V.","F – V – F.","V – V – V.","F – F – V.","V – F – F"],"correta":"A"},{"n":33,"disciplina":"Enfermagem","tema":"Epidemiologia e Vigilância em Saúde","enunciado":"Com base nos aspectos clínicos e epidemiológicos da Febre Maculosa (FMB), assinale a afirmativa correta.","alternativas":["A febre maculosa produzida pela Rickettsia parkeri apresenta quadros febris agudos e manifestações graves, frequentemente letais.","O exantema é o sinal clínico mais importante e está presente em todos os quadros de febre maculosa.","O período de incubação da FMB é, em média, de 10 dias, podendo variar de 7 a 21 dias.","A terapêutica empregada rotineiramente por um período de 14 dias deve ser mantida por 7 dias após o término da febre.","Em geral, entre o segundo e o sexto dia da doença, surge o exantema maculopapular, de evolução centrípeta e predomínio nos membros inferiores"],"correta":"E"},{"n":34,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Acerca dos cuidados a pacientes vítimas de queimaduras, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Na queimadura térmica, a meta de reanimação volêmica para pacientes adultos é manter o débito urinário em 1,0mL/kg/h e, no trauma elétrico, de 2mL/kg/h. ( ) Em pacientes idosos ou em crianças, considera -se um grande queimado aquele com Superfície Corporal Queimada - SCQ >10% e >20%, respectivamente. ( ) Segundo as recomendações do Ministério da Saúde, deve -se administrar 1 reforço da vacina antitetânica para os pacientes que receberam o último reforço há mais de 5 e a menos de 10 anos, e que apresentem queimaduras de 2º ou 3º grau. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["V – V – V.","F – F – F.","F – F – V.","V – V – F.","V – F – V"],"correta":"C"},{"n":35,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"Um paciente adulto, em tratamento de câncer de pulmão, apresentou as seguintes características: capacidade de marcha bastante prejudicada, permanecendo o dia todo sentado; mobilidade ligeiramente limitada, mas consegue fazer algumas alterações na posição do corpo; percepção sensorial levemente limitada; pele ocasionalmente úmida, requerendo troca extra da roupa de cama por dia; n utrição muito pobre, nunca come uma refeição completa; e potencial problemas com fricção e cisalhamento. De acordo com a escala de Bradem, o risco de lesão por pressão desse paciente é","alternativas":["leve.","baixo.","alto.","moderado.","muito alto"],"correta":"D"},{"n":36,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"Em um recém-nascido com sinais de asfixia, a massagem cardíaca é indicada se, após 30 segundos de ventilação com pressão positiva (VPP) e técnica adequada, a frequência cardíaca estiver abaixo de","alternativas":["60bpm.","70bpm.","80bpm.","90bpm.","100bpm"],"correta":"A"},{"n":37,"disciplina":"Enfermagem","tema":"Centro Cirúrgico","enunciado":"Considerando o protocolo de cirurgia segura do Ministério da Saúde, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A identificação do sítio cirúrgico deve ser realizada por médico membro da equipe cirúrgica antes do encaminhamento do paciente para o local de realização da cirurgia. ( ) Antes de o paciente sair da sala de cirurgia, deve ser verificado se as contagens de instrumentais cirúrgicos, compressas e agulhas estão corretas. ( ) Deve ser confirmado com o anestesista, antes da indução anestésica, se o paciente tem risco de perder mais de 500mL de sangue (mais de 7mL/kg em crianças) durante a cirurgia, a fim de garantir a preparação para essa eventualidade. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["V – V – F.","F – F – F.","V – F – V.","F – V – F.","V – V – V"],"correta":"E"},{"n":38,"disciplina":"Enfermagem","tema":"Processo de Enfermagem e SAE","enunciado":"O enfermeiro faz a ausculta cardíaca e pulmonar em uma paciente com insuficiência cardíaca. Com relação às etapas da sistematização da assistência de enfermagem, o procedimento realizado corresponde à(ao)","alternativas":["avaliação.","histórico.","diagnóstico.","implementação.","planejamento."],"correta":"B"},{"n":41,"disciplina":"Enfermagem","tema":"Diabetes Mellitus","enunciado":"Durante a avaliação de um paciente adulto com Diabetes mellitus não controlada, o Enfermeiro identificou pé diabético neuropático. Assinale a opção que indica características dessa condição.","alternativas":["Pulso pedial diminuído e pele fria.","Ausência de edema e deformidades.","Palidez com elevação e sensação dolorosa.","Dedo em garra e sensibilidade diminuída.","Cianose com declive e pele fina e brilhante"],"correta":"D"},{"n":42,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Durante o exame físico de um paciente adulto, sexo masculino, o Enfermeiro identificou sinais característicos da Tríade de Beck. Assinale a opção que os apresenta.","alternativas":["Bradicardia, hipertensão arterial e bradipneia.","Febre com calafrios, dor abdominal e icterícia.","Estase de jugular, hipofonose de bulhas e hipotensão.","Hipercoagulabilidade, estase venosa e lesão endotelial.","Coagulopatia, hipotermia e acidose metabólica"],"correta":"C"},{"n":43,"disciplina":"Enfermagem","tema":"Processo de Enfermagem e SAE","enunciado":"Assinale a opção que apresenta os eixos da CIPE que foram utilizados na construçã o do diagnóstico ventilação espontânea prejudicada.","alternativas":["Ação e tempo.","Foco e julgamento.","Ação e localização.","Julgamento e ação.","Foco e localização"],"correta":"B"},{"n":44,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"Paciente do sexo masculino, 59 anos, procurou a unidade de emergência, com queixa de diarreia e vômito há três dias. Refere piora nas últimas 24 horas, com cerca de 3 evacuações de aspecto líquido, presença de febre e 2 episódios de vômito, além de fraqueza e palpitações. O exame de gasometria arterial indicou níveis de pH = 7,30; [HCO3 –] = 16mEq/L; PaCO2 = 30mmHg; e BE = –1,0. Com base nos sintomas apresentados e nos valores da gasometria, esse paciente apresenta","alternativas":["alcalose metabólica.","acidose respiratória.","acidose metabólica.","alcalose respiratória.","acidose respiratória compensada"],"correta":"C"},{"n":45,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"Durante o tratamento dialítico a equipe de enfermagem deve estar atenta às intercorrências clínicas para que possa agir em tempo hábil. Uma dessas intercorrências é a embolia gasosa, que ocorre quando há a entrada de ar na circulação sistêmica do circuito da hemodiálise. Assinale a opção que indica os sinais característicos dessa emergência em pacientes deitados.","alternativas":["Dispneia, tosse, arritmias e dor torácica.","Náusea, vômito, cefaleia e sonolência.","Dor lombar e abdominal, calafrios e dispneia.","Câimbras, náuseas, vômito e desorientação.","Sudorese, hipotensão, rubor facial e edema de face."],"correta":"A"}]},{"codigo":"cns303","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/profissional-de-enfermagem-penf-enfermeiro-de-terapia-intensiva-nivel-vicns303-tipo-1.pdf","cargo":"Enfermeiro de Terapia Intensiva","itens":[{"n":31,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"Com base na fisiologia do sistema respiratório , analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A complacência pulmonar é definida como a maior ou menor capacidade de distensibilidade do pulmão, a uma dada variação de pressão. ( ) O volume corrente é o volume de ar inspirado ou expirado, em cada respiração normal. ( ) A capacidade vital corresponde ao volume máximo de ar movimentado nos pulmões (volume de reser va inspiratório + volume corrente + volume de reserva expiratório). As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["F – F – F.","V – F – V.","F – V – F.","V – V – V.","F – V – V"],"correta":"D"},{"n":32,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"Considerando os mecanismos de equil íbrio ácido-básico e controle do pH do sangue, analise as afirmativas a seguir. I. A acidose metabólica é a acidez excessiva do sangue, caracterizada por uma concentração anormalmente baixa de bicarbonato. II. Em pacientes com hiperventilação instala -se a acidose respiratória, na qual há o aumento de pCO 2 e a diminuição do pH. III. O termo alcalose refere -se à remoção excessiva de H + dos líquidos corporais. Está correto o que se afirma em","alternativas":["I, apenas.","II, apenas.","III, apenas.","I e II, apenas.","I e III, apenas"],"correta":"E"},{"n":33,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Acerca do tratamento medicamentoso de um paciente com choque séptico, internado em uma Unidade de Terapia Intensiva adulta, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Recomenda-se fazer a ressuscitação volêmica com cristaloides ou coloides, antes de usar o vasopressor. ( ) Nos adultos com choque séptico, a vasopressina ou epinefrina são as drogas de primeira escolha para aumentar a pressão arterial. ( ) A noradrenalina deve ser diluída em soro fisiológico ou ringer lactato, pois o soro glicosado causa instabilidade do medicamento. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["V – F – F.","F – F – F.","V – F – V.","F – V – V.","V – V – F"],"correta":"A"},{"n":34,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"Uma Gestante de 27 anos, 21ª semana de gestação, foi internada em uma unidade hospitalar apresentando um quadro de Hipertensão Gestacional Grave. Assinale a opção que indica uma característica dessa síndrome hipertensiva.","alternativas":["A presença de proteinúria.","A ocorrência de trombocitopenia.","Episódios de convulsões tônico-clônicas.","PAS ≥ 140mmHg e/ou PAD ≥ 90mmHg, ou ambos, medida em duas ocasiões com pelo menos 4 horas de intervalo.","PAS ≥ 160 mmHg e/ou PAD ≥ 110mmHg, ou ambos, medida em duas ocasiões com pelo menos 4 horas de intervalo"],"correta":"E"},{"n":35,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"O cateter de Swan -Ganz é um cateter de acesso venoso central, utilizado para a monitorização invasiva e que permite medir alguns parâmetros hemodinâmicos do paciente. Com base nas ca racterísticas desse cateter, relacione suas vias às respectivas funções. 1. Via do balão 2. Via proximal do lúmen 3. Via distal do lúmen 4. Via do lúmen do termistor ( ) Permite verificar a pressão da artéria pulmonar e a coleta de sangue venoso misto. ( ) Permite a injeção para determinação do débito cardíaco (DC) e é utilizada também para a medição da PVC. ( ) Usada para monitorar continuamente a temperatura sanguínea na artéria pulmonar. ( ) Permite o encunhamento do cateter e a medição da pressã o capilar pulmonar. Assinale a opção que apresenta a relação correta, na ordem apresentada.","alternativas":["2 – 4 – 1 – 3.","4 – 1 – 3 – 2.","3 – 2 – 4 – 1.","1 – 4 – 2 – 3.","2 – 3 – 1 – 4"],"correta":"C"},{"n":36,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Acerca dos cuidados de enfermagem a um paciente co m intubação endotraqueal, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Antes da intubação deve -se garantir a pré -oxigenação do paciente, que pode ser ofertada através de cateter nasal a 5 litros por minuto por 3 minutos. ( ) Recomenda-se verificar a pressão do balonete ( cuff) a cada 6 a 8 horas e mantê -la entre 18 a 22mmHg ou 25 a 30mmH2O, para evitar a excessiva pressão na mucosa traqueal. ( ) Deve-se avaliar continuamente o TOT para evitar torções, bloqueios e desconexão acidental que impeçam o fluxo de ar. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["F – V – V.","V – F – V.","F – V – F.","V – V – V.","F – F – F."],"correta":"A"},{"n":37,"disciplina":"Enfermagem","tema":"Administração de Medicamentos e Cálculos","enunciado":"Um dos cuidados de enfermagem na administração da nutrição parenteral é verificar a compatibilidade entre o acesso venoso do paciente e a osmolaridade recomendada. Segundo a Sociedade Americana de Nutrição Enteral e Parenteral, a osmolaridade máxima recomendada, no caso da Nutrição Parenteral Periférica, é de","alternativas":["200mOsm/L.","400mOsm/L.","700mOsm/L.","900mOsm/L.","1200mOsm/L"],"correta":"D"},{"n":38,"disciplina":"Enfermagem","tema":"Gestão em Enfermagem","enunciado":"De acordo com a Resolução do Ministério da Saúde que dispõe sobre os requisitos mínimos para o funcionamento das Unidades de Terapia Intens iva – UTI, cada unidade deve dispor de alguns equipamentos específicos, em quantidades determinadas. Com base nessa normativa, as quantidades mínimas de eletrocardiógrafo portátil e desfibrilador em uma UTI, devem ser de, respectivamente,","alternativas":["1 para cada 5 leitos e 1 para cada 1 leito.","1 para cada 6 leitos e 1 para cada 3 leitos.","1 para cada 7 leitos e 1 para cada 1 leito.","1 para cada 8 leitos e 1 para cada 2 leitos.","1 para cada 10 leitos e 1 para cada 5 leitos"],"correta":"E"},{"n":39,"disciplina":"Enfermagem","tema":"Gestão em Enfermagem","enunciado":"Em relação à Comissão Hospitalar de Organização e Qualificação da Atenção ao Paciente Crítico (COHPAC), assinale a afirmativa correta.","alternativas":["É responsável, entre outras coisas, pela regulação e avaliação das políticas públicas voltadas ao paciente crítico.","É responsável por elaborar e implementar o Plano Hospitalar de Atenção ao Paciente Crítico.","Deve ser composta minimamente pelo diretor técnico e pelo diretor administrativo da Instituição de Saúde.","É obrigatória para os estabelecimentos de Saúde da rede pública e facultativa para as instituições privadas.","A comissão, a critério de cada instituição, poderá apresentar relatório periódico de resultados aos gestores do SUS"],"correta":"B"},{"n":40,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Na monitorização de um paciente, a capnografia permite medir","alternativas":["a profundidade da sedação.","o nível de óxido nitroso e de agentes halogenados.","a pressão parcial de CO2 durante o ciclo respiratório.","o bloqueio e a reversão do bloqueio neuromuscular.","o volume de sangue bombeado pelo coração em um minuto"],"correta":"C"},{"n":41,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Um paciente que sofreu múltiplas fraturas devido a uma queda durante a atividade laboral, apresentou entre outros sinais e sintomas, otorreia, sinal do duplo halo e equimose na região mastoidea. Esses sinais são característicos de","alternativas":["concussão.","lesão axonal difusa.","hematoma subdural agudo.","fratura de base de crânio.","fraturas lineares não deprimidas"],"correta":"D"},{"n":42,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"No monitoramento do ciclo respiratório de um ventilador mecânico, o parâmetro que corresponde à pressão de acomodação dos alvéolos no final da inspiração (pressão inspiratória final), é denominado","alternativas":["drive pressure.","pressão de platô.","volume corrente.","fração inspirada de oxigênio.","pico de pressão inspiratório (PIP)"],"correta":"B"},{"n":43,"disciplina":"Enfermagem","tema":"Controle de Infecção e Biossegurança","enunciado":"Considerando as recomendações da ANVISA acerca das medidas de prevenção de infecção relacionada à assistência à saúde, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A utilização da cânula orotraqueal, com um sistema de aspiração de secreção subglótica contínua ou intermitente, é recomendada para pacientes que irão permanecer sob Ventilação Mecânica acima de 48h ou 72h. ( ) Nos cateteres semi -implantáveis ou tunelizados, deve -se manter o sítio de inserção coberto, mesm o após a cicatrização do óstio. ( ) A punção do reservatório do cateter totalmente implantável deve ser realizada com agulha angulada (tipo Huber), própria para uso na membrana do reservatório. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["V – F – V.","F – F – F.","V – F – F.","F – V – F.","V – V – V"],"correta":"A"},{"n":44,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"No atendimento a um paciente com suspeita de Infarto Agudo do Miocárdio - IAM, uma das condutas é a dosagem sérica de biomarcadores cardíacos para confirmação do diagnóstico. Nesse caso, o biomarcador mais específico e sensível para o diagnóstico de lesão isquêmica do miocárdio é a enzima","alternativas":["CK-MB.","Troponina.","Mioglobina.","Transaminase.","Desidrogenase Lática"],"correta":"B"}]},{"codigo":"cns304","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/profissional-de-enfermagem-penf-enfermeiro-neonatologista-nivel-vicns304-tipo-1.pdf","cargo":"Enfermeiro Neonatologista","itens":[{"n":31,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"Sobre as avaliações e os cuidados iniciais dispensados ao recém - nascido logo após o parto, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O perímetro torácico deve ser medido passando a fita métrica pela linha intermamilar e é, em média, 2cm menor do que o perímetro cefálico. ( ) Um recém -nascido com hipotermia leve apresenta temperatura axilar entre 36 e 36,4C. ( ) Logo após o nascimento, os recém-nascidos de mulheres com HBV devem receber imunoglobulina humana anti -hepatite B (IGHAHB) e a primeira dose do esquema vacinal da vacina hepatite B. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["F – V – F.","V – V – V.","F – F – V.","V – V – F.","F – V – V"],"correta":"B"},{"n":32,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"No Brasil, a taxa de mortalidade neonatal tardia está entre os indicadores básicos para a saúde. Esse indicador diz respeito aos óbitos ocorridos no período de","alternativas":["0 aos 6 dias de vida.","8 aos 15 dias de vida.","10 aos 20 dias de vida.","7 aos 27 dias de vida.","15 aos 36 dias de vida"],"correta":"D"},{"n":33,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"Na assistência ao recém -nascido ≥ 34 semanas, saudável e com boa vitalidade ao nascer, recomenda -se clampear o cordão umbilical no mínimo","alternativas":["30 segundos após o nascimento.","40 segundos após o nascimento.","50 segundos após o nascimento.","60 segundos após o nascimento.","90 segundos após o nascimento"],"correta":"D"},{"n":34,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"Após o nascimento, um recém -nascido apresentou edema de couro cabeludo, depressível, inicialmente restrito à área de apresentação do parto. Essa é uma das alterações mais frequentes encontradas após o nascimento, denominada","alternativas":["lanugo.","céfalo-hematoma.","bossa serossanguínea.","hematoma subgaleal.","mancha mongólica"],"correta":"C"},{"n":35,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"Acerca das etapas do Método Canguru, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A primeira etapa tem início no pré -natal, com a identificação de situação de risco que indique a necessidade de cuidados especializados para a gestante, os quais podem ou não acarretar a internação do recém -nascido (RN) em uma Unidade Neonatal. ( ) Entre os critérios de elegibilidade da criança para a segunda etapa do método, realizada na Unidade de Cuidado Intermediário Canguru – UCINCa, estão nutrição enteral plena e peso mínimo de 1.250g. ( ) O principal critério para que a criança tenha alta da segunda etapa é a sucção exclusiva ao peito sem necessidade de complemento, mesmo que excepcionalmente. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["V – F – V.","F – V – F.","V – V – V.","F – F – F.","V – V – F"],"correta":"E"},{"n":36,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"Acerca dos procedimentos realizados em uma Unidade de Internação Neonatal, assinale a afirmativa correta.","alternativas":["A paracentese, quando indicada, deve ser realizada no quadrante superior direito.","O cateter epicutâneo -cava é um dispositivo específico para o cateterismo umbilical arterial ou venoso.","Quando necessária, a punção do calcanhar deve ser realizada na região central para evitar a incidência de osteomielite.","Uma das indicações do Cateter Central de Inserção Periférica é a necessidade de monitorização de pressão arterial invasiva.","O procedimento de intubação deve ser interrompido sempre que a manobr a exceder 20 segundos, para que o RN seja oxigenado"],"correta":"E"},{"n":37,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"Na avaliação de um recém -nascido a termo, com acúmulo de bilirrubina na esclera e na pele e com BT = 13mg/dL, o enfermeiro o classificou em Zona de Kramer 3. Essa classificação corresponde à progressão da icterícia","alternativas":["somente na face.","até os joelhos e cotovelos.","na região da cabeça e do pescoço.","da cabeça até a cicatriz umbilical.","até os tornozelos e antebraços"],"correta":"B"},{"n":38,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"A sepse neonatal precoce é a que ocorre nas primeiras 48 horas de vida e está relacionada diretamente a fatores gestacionais e/ou do período periparto. Assinale a opção que indica um fator de risco para essa síndrome clínica.","alternativas":["Prematuridade.","Febre materna acima de 36,8C.","Batimentos cardíacos fetais superiores a 110bpm.","Ruptura prematura de membranas amnióticas por tempo superior a 6 horas.","Infecção urinária materna ocorrida no primeiro trimestre da gestação, tratada ou não."],"correta":"A"},{"n":39,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"Um recém-nascido apresentou, no 5º minuto de vida, respiração forte e regular, careta em resposta a estímulos, boa flexão dos membros, FC = 102bpm e corpo róseo com cianose de extremidades. Com base na avaliação fisiológica por meio do boletim de Apgar, essas características indicam","alternativas":["asfixia leve.","asfixia moderada.","asfixia grave.","asfixia severa.","boa vitalidade"],"correta":"E"},{"n":40,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"Entre os fatores que correspondem a uma contraindicação permanente para a amamentação de um recém -nascido a termo e saudável, está a seguinte condição materna:","alternativas":["tabagismo.","tuberculose.","hepatite C.","infecção pelo HIV.","infecção pela Covid-19"],"correta":"D"},{"n":41,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"Com base nas diretrizes de reanimação e cuidados emergenciais ao recém -nascido, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A aspiração de boca e narinas é recomendada de rotina para RN ≥34 semanas, independentemente do aspecto do líquido amniótico. ( ) Se após os cuidados para manter a temperatura e as vias aéreas pérvias, o RN apresentar FC <100 bpm, apneia ou respiração irregular, há indicação da VPP (ventilação com pressão positiva), nos primeiros 60 segundos de vida. ( ) A adrenalina está indicada quando a ventilação adequada e a massagem cardíaca efetiva não produziram elevação da FC para valores > 60 bpm. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["F – V – F.","V – V – V.","F – V – V.","V – F – V.","F – F – F"],"correta":"C"},{"n":42,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"O recém -nascido, após a realização de um procedimento , apresentou inquietação, padrão respiratório normal, expressão facial relaxada, resmungos, braços fletidos e pernas relaxadas. Com base na escala de NIPS para avaliação da dor, a pontuação obtida indica que este RN está","alternativas":["sem dor.","com dor leve.","com dor moderada.","com dor forte.","com dor insuportável"],"correta":"A"},{"n":43,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"Acerca das normas e orientações relacionadas à transfusão de hemocomponentes em recém -nascidos – RN, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A exsanguineotransfusão (EXT) é a substituição do sangue do RN, através da retirada de múltiplas alíquotas, pela mesma quantidade de sangue de um doador homólogo. ( ) O tempo de administração do concentrado de hemácias em um RN não deve exceder 8 horas de infusão. ( ) Uma das indicações de transfusão de concentrado de hemácias em RN é FC > 180bpm ou FR > 80rpm por 24 horas sem causa aparente. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["V – F – V.","F – V – F.","F – F – V.","V – V – V.","F – F – F"],"correta":"A"},{"n":44,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"Em um recém-nascido a termo e com boa vitalidade, a SatO 2 alvo pré-ductal entre o 5º e o 10º minuto, após o nascimento, está entre","alternativas":["60-70%.","70-80%.","80-90%.","85-95%.","95-98%"],"correta":"C"},{"n":45,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"A orientação da ANVISA para prevenir infecção da corrente sanguínea é que o tempo de permanência do cateter umbilical venoso seja limitado a um período de","alternativas":["2 a 8 dias.","7 a 14 dias.","até 18 dias.","até 21 dias.","até 28 dias."],"correta":"B"}]},{"codigo":"cns305","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/profissional-de-enfermagem-penf-enfermeiro-obstetra-nivel-vicns305-tipo-1.pdf","cargo":"Enfermeiro Obstetra","itens":[{"n":31,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"O acolhimento em obstetrícia pressupõe um atendimento humanizado incluindo o direito a uma assistência digna e respeitosa durante toda a gravidez, parto e puerpério, assim como o direito de estar livre da violência e discriminação. Com base nas disposições do Ministério da Saúde acerca dos atos que caracterizam violência obstétrica , analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Tratar a gestante ou parturiente de forma agres siva, não empática, grosseira, zombeteira, ou de qualquer outra forma que a faça se sentir mal pelo tratamento recebido. ( ) Impedir que a mulher seja acompanhada por alguém de sua preferência durante todo o trabalho de parto. ( ) Realizar a episiotomi a quando esta não for realmente imprescindível. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["F – V – F.","V – V – V.","F – F – V.","V – F – V.","F – V – V"],"correta":"B"},{"n":32,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"Recomenda-se o cuidado da parturiente em maternidade baseada em hospital, com presença de médico obstetra, se este não for o profissional que assiste a mulher, na presença de qualquer uma das seguintes condições:","alternativas":["apresentação cefálica alta ou móvel em nulípara.","frequência cardíaca fetal (FCF) < 120 ou > 140bpm.","temperatura de 37,5 C ou mais em uma única medida ou 37C em 2 ocasiões, em período de 1 hora.","PA sistólica ≥ 145mmHg ou PA diastólica ≥ 95mmHg em uma única medida.","frequência cardíaca materna >110bpm em 2 ocasiões, com 30 minutos de intervalo"],"correta":"A"},{"n":33,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"Uma gestante na 26ª semana de gestação deu entrada na unidade de saúde apresentando padrão respiratório ineficaz; saturação de O² = 94% em ar ambiente; PAS = 165 e PAD = 110mmHg, dor de cabeça, de estômago, e temperatura axilar = 40C. De acordo com o protocolo de acolhimento e classificação de risco em obstetrícia, essa gestante deve receber a classificação","alternativas":["vermelha (atendimento imediato).","laranja (atendimento em até 15 minutos).","amarela (atendimento em até 30 minutos).","verde (atendimento em até 120 minutos).","azul (atendimento não prioritário)"],"correta":"B"},{"n":34,"disciplina":"Enfermagem","tema":"Epidemiologia e Vigilância em Saúde","enunciado":"Acerca do indicador razão de mortalidade materna , analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) É o número de óbitos maternos por 100 mil nascidos vivos de mães residentes em determinado espaço geográfico, em um determinado período de tempo. ( ) Estima a frequência de óbitos femininos, ocorridos até 42 dias após o término da gestação, de causas lig adas ou não à gravidez, parto e puerpério. ( ) São considerados, no conceito de morte materna, os óbitos por tétano obstétrico e por transtornos mentais e comportamentais associados ao puerpério. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["V – V – V.","F – V – F.","V – F – V.","F – F – V.","V – F – F"],"correta":"C"},{"n":35,"disciplina":"Enfermagem","tema":"Ética e Legislação em Enfermagem","enunciado":"Com base nas disposições do Código de Ética dos Profissionais de Enfermagem, analise as afirmativas a seguir. I. A ação, omissão ou conivência que implique em desobediência ou inobservância às disposições do Código de Ética dos Profissionais de Enfermagem é considerada infração ética e disciplinar. II. A advertência verbal consiste na admoestação ao infrator, de forma reservada, que será registrada no prontuário do mesmo, na presença de duas testemunhas. III. A penalidade de cassação do direito ao exercício profissional é de competência do Conselho Federal de Enfermagem. Está correto o que se afirma em","alternativas":["I, apenas.","II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III"],"correta":"E"},{"n":36,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"De acordo com as orientações do Ministério da Saúde, uma gestante deve passar por, no mínimo, 6 consultas de pré -natal durante a gestação. Nesse caso, o cronograma recomendado estabelece a realização de consultas","alternativas":["bimestrais, até a 20ª semana.","quinzenais, da 36ª até a 41ª semana.","mensais, da 25ª até a 35ª semana.","quinzenais, da 28ª até a 36ª semana.","semanais, da a 20ª até a 28ª semana"],"correta":"D"},{"n":37,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"De acordo com as recomendações do Mi nistério da Saúde, a gestante, até o final da gestação, deve receber diariamente","alternativas":["40mg de ferro elementar.","200µg de ácido fólico.","50mg de ferro elementar.","300µg de ácido fólico.","30mg de ferro elementar."],"correta":"A"},{"n":38,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"Assinale a opção que indica o exame de rotina que deve ser solicitado no segundo trimestre de gestação em um pré -natal de baixo risco.","alternativas":["Hemograma.","Toxoplasmose IgM e IgG.","Tipagem sanguínea e fator Rh.","Exame da secreção vaginal, se houver indicação clínica.","Teste de tolerância para glicose com 75g, se houver fator de risco materno"],"correta":"E"},{"n":39,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"De acordo com as recomendações do Ministério da Saúde, uma mulher de 28 anos que apresentou Lesão de Baixo Grau (LSIL) no resultado do exame citopatológico deve","alternativas":["repetir a citologia em 1 ano.","repetir a citologia em 3 anos.","repetir a citologia em 6 meses.","repetir a citologia em 12 meses.","ser encaminhada para colposcopia"],"correta":"C"},{"n":40,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"Com base nas orientações do Ministério da Saúde para avaliação da presença de edema em uma gestante durante as consultas de pré-natal, analise as afirmativas a seguir. I. O resultado (+++) corresponde à presença de edema em membros inferiores + ganho de peso + hipertensão. II. Na presença de edema em fa ce, membros e região sacra, independentemente de ganho de peso e hipertensão, deve - se suspeitar de pré -eclâmpsia e encaminhar a paciente para avaliação médica e pré-natal de alto risco. III. O edema unilateral de MMII, com sinais flogísticos e dor, sugere a presença de tromboflebite e trombose venosa profunda. Está correto o que se afirma em","alternativas":["I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III"],"correta":"D"},{"n":41,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"Uma gestante com úlcera genital e confirmação diagnóstica de sífilis, deve ser tratada com","alternativas":["doxiciclina.","ceftriaxona.","azitromicina.","ciprofloxacino.","penicilina G benzatina"],"correta":"E"},{"n":42,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"Acerca da assistência ao parto normal , analise as afirmativas a seguir e assinale (V) para a afirmativa e (F) para a falsa. ( ) Recomenda-se o uso de agentes antiespasmódicos para prevenção de atraso no trabalho de parto. ( ) Se a ocitocina for indicada, deve -se utilizar esquema de baixa dose e assegurar que os incrementos na dose não sejam mais frequentes do que a cada 30 minutos. ( ) Se for necessário realizar uma episiotomia, recomenda -se a médio-lateral originando na fúrcula vaginal e direcionando para o lado direito, com um ângulo do eixo vertical entre 45 e 60 graus. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["V – F – V.","F – V – V.","V – V – V.","F – F – F.","V – F – F"],"correta":"B"},{"n":43,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"Um dos sinais de certeza de gravidez é a presença de batimentos cardíacos fetais (BCF), detectados pelo sonar a partir da","alternativas":["9ª semana de gestação.","10ª semana de gestação.","12ª semana de gestação.","15ª semana de gestação.","20ª semana de gestação"],"correta":"C"},{"n":44,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"Uma das medidas que deve ser garantida à mulher vítima de violência sexual é a Profilaxia Pós-Exposição ao HIV (PEP). Essa medida deve ser realizada no máximo em até","alternativas":["12 horas.","24 horas.","48 horas.","72 horas.","96 horas"],"correta":"D"},{"n":45,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"De acordo com as orientações do Ministério da Saúde, assinale a opção que indica o critério usado para classificar uma RN como alto risco ao nascer.","alternativas":["Frequência respiratória > 60irpm.","Idade gestacional ≥ 42 semanas.","Temperatura axilar > 36C.","Peso ao nascer < 2.500g.","Reanimação sem VPP."],"correta":"A"}]},{"codigo":"cns306","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/profissional-de-enfermagem-penf-enfermeiro-oncologista-nivel-vicns306-tipo-1.pdf","cargo":"Enfermeiro Oncologista","itens":[{"n":31,"disciplina":"Enfermagem","tema":"Controle de Infecção e Biossegurança","enunciado":"De acordo com as recomendações da ANVISA para prevenção e controle de infecção de corrente sanguínea, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O uso de pomadas anti microbianas em sítio de inserção deve ser limitado para cateteres de hemodiálise, após cada sessão. ( ) Deve-se trocar o equipo e o dispositivo complementar de infusões lipídicas a cada 12 horas. ( ) A limpeza e a desinfecção da superfície e do painel das bombas de infusão devem ser realizadas a cada 24 horas e na troca de paciente. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["F – F – F.","V – F – V.","F – F – V.","V – V – V.","F – V – F"],"correta":"D"},{"n":32,"disciplina":"Enfermagem","tema":"Administração de Medicamentos e Cálculos","enunciado":"Acerca da interação medicamentosa entre o metotrexato e o ácido folínico, assinale a afirmativa correta.","alternativas":["A interação ocasiona hipoglicemia severa.","A interação aumenta o risco de mielossupressão.","O ácido folínico aumenta a citoxicidade do metotrexato.","O metotrexato anula o efeito terapêutico do acido folínico.","O ácido folínico diminui a citoxicidade do metotrexato"],"correta":"E"},{"n":33,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"Após o tratamento quimioterápico, um paciente adulto com linfoma não Hodgkin (LNH) apresentou recaída precoce. Isso significa","alternativas":["doença ativa após 1 ano de tratamento.","doença ativa com menos de 1 ano de tratamento.","doença resistente aos protocolos de quimioterapia.","contagem de células neoplásicas menor ou igual a 20% na medula óssea.","contagem de células neoplásicas menor ou igual a 5% na medula óssea"],"correta":"B"},{"n":34,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"De acordo com a classificação da Organização Mundial da Saúde (OMS), um paciente em tratamento quimioterápico com mucosite Grau 2 apresenta","alternativas":["eritema e dor.","necrose tecidual na boca e na garganta.","ulceração, mas consegue ingerir sólidos.","ulceração e só consegue ingerir líquidos.","sangramento espontâneo com risco de morte"],"correta":"C"},{"n":35,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"Na assistência ao paciente oncológico, considerando o mecanismo de ação da ciclofosf amida, assinale a opção que indica um dos cuidados de enfermagem.","alternativas":["Aferir pressão arterial antes e após a infusão da droga.","Realizar balanço hídrico rigoroso e hiperhidratar o paciente.","Administrar manitol e controlar a ocorrência de náuseas e vômitos.","Aplicar colírio de dexametasona 0,1% de duas a quatro vezes ao dia.","Certificar-se da ausência de patologia cardiocirculatória antes da infusão da droga"],"correta":"B"},{"n":36,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Sobre a Política Nacional de Atenção às Urgências, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Um dos componentes da Rede de Atenção às Urgências é a Promoção, Prevenção e Vigilância à Saúde. ( ) Entre as diretrizes da Rede de Atenção às Urgências está a articulação in terfederativa entre os diversos gestores, desenvolvendo atuação solidária, responsável e compartilhada. ( ) O Componente Força Nacional de Saúde do SUS objetiva a ampliação do acesso, o fortalecimento do vínculo e a responsabilização e o primeiro cuidado às urgências e emergências. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["V – V – F.","F – F – V.","V – V – V.","F – V – F.","V – F – V"],"correta":"A"},{"n":37,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"Assinale a opção que apresenta uma droga irritante, sem potencial vesicante, utilizada no tratamento quimioterápico.","alternativas":["Dacarbazina.","Doxorrubicina.","Cisplatina.","Mitoxantrona.","Idarrubicina"],"correta":"C"},{"n":38,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"De acordo com as recomendações do Ministério da Saúde, um paciente no pós -tratamento de câncer de cólon estádio I deve repetir a colonoscopia em","alternativas":["1 ano e, posteriormente, a cada 2 anos, com presença ou não de pólipo.","2 anos e, posteriormente, a cada ano, caso haja presença de pólipo.","6 meses e, posteriormente, a cada ano, com presença ou não de pólipo.","1 ano e, posteriormente, a cada 3 a 5 anos, caso não haja presença de pólipo.","2 anos e, posteriormente, a cada 2 a 3 anos, caso não haja presença de pólipo."],"correta":"D"},{"n":39,"disciplina":"Enfermagem","tema":"Gestão em Enfermagem","enunciado":"O enfermeiro exerce uma liderança carismática e é capaz de engajar, inspirar e motivar os colaboradores, de modo que eles contribuam para que a organização seja bem-sucedida no alcance dos seus objetivos. Ele está exercendo a liderança","alternativas":["motivacional.","transacional.","estratégica.","situacional.","transformacional"],"correta":"E"},{"n":40,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"Um paciente em tratamento oncológico apresentou sinais característicos de intoxicação por morfina. Assinale a opção que indica o medicamento que deve ser usado para reverter esse efeito.","alternativas":["Lanexat.","Naloxona.","Etomidadto.","Flumazenil.","Midazolam"],"correta":"B"},{"n":41,"disciplina":"Enfermagem","tema":"Ética e Legislação em Enfermagem","enunciado":"Sobre as competências privativas do Enfermeiro em Quimioterapia Antineoplásica, analise as afirmativas a seguir. I. Registrar informações pertinentes à assistência de Enfermagem no prontuário do paciente e demais documentos. II. Conhecer e cumprir os protocolos terapêuticos de Enfermagem na prevenção, tratamento e minimização dos efeitos colaterais em clientes submetidos ao tratamento quimioterápico antineoplásico. III. Participar da definição da política de recursos humanos, da aquisição de material e da disposição da área física, necessários à assistência integral dos pacientes. Está correto o que se afirma em","alternativas":["I, apenas.","I e II, apenas.","II, apenas.","I e III, apenas.","III, apenas"],"correta":"E"},{"n":42,"disciplina":"Enfermagem","tema":"Segurança do Paciente","enunciado":"Acerca das medidas de segurança na assistência ao paciente oncológico, analise as afirmativas a seguir e assinale (V) para a verdadeira (F) para a falsa. ( ) Um evento ocorrido durante uma sessão de quimioterapia que resultou em dan o desnecessário à saúde do paciente, é considerado um incidente. ( ) Os antineoplásicos de uso oral e parenteral são considerados medicamentos potencialmente perigosos e, por isso, uma das recomendações de segurança é adotar protocolos claros e detalhados para sua utilização. ( ) O extravasamento de doxorrubicina durante a administração intravenosa pode produzir dor local, lesões teciduais graves e necrose. As afirmativas são, na ordem apresentada, respectivamente,","alternativas":["V – V – V.","F – V – F.","V – F – V.","F – F – F.","V – F – F"],"correta":"A"},{"n":43,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"A quimioterapia indicada após o tratamento cirúrgico curativo, quando o paciente não apresenta qualquer evidência de neoplasia maligna detectável por exame físico e exames complementares, é denominada","alternativas":["prévia.","curativa.","adjuvante.","paliativa.","neoadjuvante"],"correta":"C"},{"n":44,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"Na assistência a um paciente em tratamento oncológico, o enfermeiro aplicou a escala de performance Karnofsky (KPS) e obteve o valor de 50%. Esse percentual equivale à seguinte capacidade funcional:","alternativas":["muito debilitado, necessita de suporte.","cuida de si mesmo, mas não é capaz de trabalhar.","necessita de assistência ocasional, mas é capaz de trabalhar.","necessita de assistência considerável e cuidados médicos frequentes.","mínimos sinais e sintomas, capaz de realizar suas atividades com esforço"],"correta":"D"},{"n":45,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"Um paciente adulto, em tratamento de câncer de pulmão, apresentou dispneia, edema de face, edema de membro superior direito, distensão das veias do pescoço, circulação colateral visível e pletora facial. Assinale a opção que indica a urgência oncológica correspondente a esses sintomas.","alternativas":["Neutropenia febril.","Compressão medular.","Síndrome de lise tumoral.","Síndrome de veia cava superior.","Hipercalcemia da malignidade."],"correta":"D"}]}] as const;
export async function sincronizarFGVFhemig2023(){
 const usuario=await prisma.usuario.findFirst({orderBy:{id:"asc"},select:{id:true}});
 if(!usuario)return {inseridas:0,existentes:0,repetidas:0};
 const norm=(s:string)=>s.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
 const banco=await prisma.questao.findMany({where:{fonte:FONTE_PROVAS_REAIS},select:{enunciado:true}});
 const vistos=new Set(banco.map(q=>norm(q.enunciado)));
 const disciplinas=new Map<string,number>();
 let inseridas=0,existentes=0,repetidas=0;
 for(const lote of LOTES)for(const q of lote.itens){
  if(!q.enunciado.trim()||q.alternativas.length!==5||q.alternativas.some(a=>!a.trim())||
   new Set(q.alternativas.map(a=>a.trim().toLowerCase())).size!==5||!["A","B","C","D","E"].includes(q.correta))
   throw new Error("[fhemig-2023] Item inválido: "+lote.codigo+"-"+q.n);
  const origemId="fgv-fhemig-2023-"+lote.codigo+"-tipo1-q"+String(q.n).padStart(2,"0");
  if(await prisma.questao.findFirst({where:{fonte:FONTE_PROVAS_REAIS,origemId},select:{id:true}})){existentes++;continue;}
  const chave=norm(q.enunciado);if(vistos.has(chave)){repetidas++;continue;}
  let disciplinaId=disciplinas.get(q.disciplina);
  if(!disciplinaId){
   let d=await prisma.disciplina.findFirst({where:{usuarioId:usuario.id,nome:{equals:q.disciplina,mode:"insensitive"}},select:{id:true}});
   if(!d)d=await prisma.disciplina.create({data:{usuarioId:usuario.id,nome:q.disciplina},select:{id:true}});
   disciplinaId=d.id;disciplinas.set(q.disciplina,disciplinaId);
  }
  await prisma.questao.create({data:{
    usuarioId:usuario.id,disciplinaId,fonte:FONTE_PROVAS_REAIS,origemId,tema:q.tema,dificuldade:"medio",
    banca:"FGV",orgao:"Fundação Hospitalar do Estado de Minas Gerais - FHEMIG",ano:2023,cargo:lote.cargo,
    fonteUrl:lote.prova,enunciado:q.enunciado,
    explicacao:"FGV/FHEMIG 2023, "+lote.cargo+", Tipo 1, questão "+q.n+
      ". Gabarito DEFINITIVO: alternativa "+q.correta+". Prova: "+lote.prova+" | Gabarito: "+GABARITO_URL,
    alternativas:{create:q.alternativas.map((texto,i)=>({texto:"ABCDE"[i]+") "+texto,correta:"ABCDE"[i]===q.correta}))}
  }});
  vistos.add(chave);inseridas++;
 }
 console.log("[fhemig-2023] "+inseridas+" inseridas; "+existentes+" existentes; "+repetidas+" repetidas ignoradas.");
 return {inseridas,existentes,repetidas};
}
